genereti_widget_values.guide:
{
  "format": "genereti-guide",
  "version": 1,
  "id": "genereticore-04-genereti-vision",
  "title": "Genereti sketch to local vision",
  "summary": "Learn on this editable graph. Inference starts only when you press Run.",
  "steps": [
    {
      "title": "Start the artwork",
      "text": "ꘇ livecode · moving circle · press editor Run\n\nThe saved sketch starts on open. Use editor Run after edits; an orange circle moves on blue.",
      "target": {
        "nodeType": "GeneretiLivecode",
        "nodeId": 2,
        "ref": "f37977de-ffc1-58cf-8fa1-a14bebbde963",
        "part": "code"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    },
    {
      "title": "Prepare the local model",
      "text": "ꘅ Local Vision · inspect one queued frame\n\nClick ↓ if the vision model is missing. No frame is sent to cloud inference.",
      "target": {
        "nodeType": "GeneretiCoreVision",
        "nodeId": 3,
        "ref": "32a1f454-dc87-51a2-9cf8-dbf52ed21176",
        "part": "toolbar"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    },
    {
      "title": "Sample a frame",
      "text": "ꘇ livecode · moving circle · press editor Run\n\nPress the TOP Comfy Run. It captures one frame from p5 and submits local analysis.",
      "target": {
        "nodeType": "GeneretiLivecode",
        "nodeId": 2,
        "ref": "f37977de-ffc1-58cf-8fa1-a14bebbde963",
        "part": "preview"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    },
    {
      "title": "Read the answer",
      "text": "ꘅ Text / JSON Viewer · Read the result\n\nRead the result. Edit the p5 color and queue a second observation. Animation and inference have separate clocks.",
      "target": {
        "nodeType": "GeneretiCoreResult",
        "nodeId": 4,
        "ref": "1f7feb9e-b73a-5e76-908e-bf6c536a7a5c",
        "part": "node"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    }
  ]
}

